<script setup lang="ts">
import {computed,nextTick,onMounted,ref,watch} from 'vue';
import {Workflow,Play,Save,Download,Upload,RefreshCw,Check,ChevronLeft,ChevronRight,X,Image,Link2,Search,ArrowRight,FileJson} from 'lucide-vue-next';
import WorkflowCanvas from './WorkflowCanvas.vue';
import {WORKFLOW_TEMPLATES,createTemplate,normalizeYoutube,normalizeAsset,runWorkflow,parseWorkflowGraph,applyRegistryState,exportRegistryState,installLocalPackage,uninstallLocalModule,setBuiltinEnabled,setLocalModuleEnabled,listAllModules,parseModulePackage,exampleTagDictionaryPackage,type WorkflowGraph,type NormalizedRecord,type RecordPreview,type IdentityBinding} from './workflow';
import type {Asset,Snapshot} from './types';

const props=defineProps<{library:Snapshot;selectionRequest?:{kind:'local'|'youtube';ids:string[];nonce:number}}>();
const emit=defineEmits<{refresh:[];navigate:[path:string]}>();
const graph=ref<WorkflowGraph>(createTemplate(WORKFLOW_TEMPLATES[0]!.key));
const template=ref(WORKFLOW_TEMPLATES[0]!.key),tab=ref('canvas'),busy=ref(false),error=ref(''),message=ref('');
const store=ref<any>({drafts:[],runs:[],metadata:[],playlists:[],modules:{modules:[],disabledBuiltinIds:[]},identityLedger:{items:[]}}),channel=ref<any>({videos:[]});
const imported=ref<any[]|null>(null),importedName=ref(''),selection=ref(new Set<string>()),search=ref(''),kind=ref('youtube'),privacy=ref(''),page=ref(1);
const preview=ref<ReturnType<typeof runWorkflow>|null>(null),approved=ref(new Set<string>()),run=ref<any>(null),focus=ref<NormalizedRecord|null>(null);
const overrides=ref<Record<string,Record<string,any>>>({}),frames=ref<Record<string,{asset_id:string;time_seconds:number;data_url:string}>>({});
const player=ref<HTMLVideoElement>(),assetLink=ref(''),canvasRef=ref<InstanceType<typeof WorkflowCanvas>>(),previewFilter=ref(''),previewPage=ref(1);
const identityDraft=ref(''),moduleCatalog=ref(listAllModules());
const key=(r:{kind:string;id:string})=>`${r.kind}:${r.id}`;
const copy=<T,>(v:T):T=>JSON.parse(JSON.stringify(v));
function syncModulesFromStore(){applyRegistryState(store.value.modules);moduleCatalog.value=listAllModules();}
async function api(path:string,body?:unknown){const response=await fetch('/api'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const value=await response.json();if(!response.ok)throw Error(value.error??`请求失败 ${response.status}`);return value;}
async function perform(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function load(preserve=false){const results=await Promise.allSettled([api('/workflows'),api('/youtube')]);if(results[0].status==='fulfilled'){store.value=results[0].value;syncModulesFromStore();}else error.value=results[0].reason.message;if(results[1].status==='fulfilled')channel.value=results[1].value;else error.value=[error.value,results[1].reason.message].filter(Boolean).join('；');if(!preserve){preview.value=null;run.value=null;approved.value=new Set();}}
async function persistModules(){store.value.modules=await api('/workflows/modules',exportRegistryState());syncModulesFromStore();}
async function toggleModule(id:string,enabled:boolean,builtin:boolean){await perform(async()=>{if(builtin)setBuiltinEnabled(id,enabled);else setLocalModuleEnabled(id,enabled);await persistModules();message.value=enabled?'模块已启用':'模块已禁用';preview.value=null;});}
async function installModuleFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(file)await perform(async()=>{if(file.size>1024*1024)throw Error('模块包过大');const pkg=parseModulePackage(JSON.parse(await file.text()));installLocalPackage(pkg,true);await api('/workflows/modules/install',{package:pkg,trusted:true});await load(true);message.value=`已安装模块 ${pkg.id}`;});input.value='';}
async function installExample(){await perform(async()=>{const pkg=exampleTagDictionaryPackage();installLocalPackage(pkg,true);await api('/workflows/modules/install',{package:pkg,trusted:true});await load(true);message.value='已安装示例标签词典模块';});}
async function removeModule(id:string){await perform(async()=>{uninstallLocalModule(id);await api(`/workflows/modules/${encodeURIComponent(id)}/uninstall`,{});await load(true);message.value='已卸载本地模块';});}
async function saveIdentityLedger(){await perform(async()=>{const items=identityDraft.value.split(/\n+/).map(line=>line.trim()).filter(Boolean).map(line=>{const [platform,roomId,creator,...aliases]=line.split('|').map(x=>x.trim());if(!platform||!roomId||!creator)throw Error('每行格式：platform|roomId|creator|可选别名');return {platform,roomId,creator,aliases:aliases.filter(Boolean)};});store.value.identityLedger=await api('/workflows/identity-ledger',{items});message.value=`已保存 ${items.length} 条身份台账`;preview.value=null;});}
function loadIdentityDraft(){const items=store.value.identityLedger?.items??[];identityDraft.value=items.map((i:any)=>[i.platform,i.roomId,i.creator,...(i.aliases??[])].join('|')).join('\n');}
function savedRecord(record:NormalizedRecord):Record<string,any>{const list=Array.isArray(store.value.metadata)?store.value.metadata:Object.values(store.value.metadata??{});return list.find((m:any)=>m.id===record.id&&m.kind===record.kind)??{};}
function savedMetadata(record:NormalizedRecord):Record<string,any>{return savedRecord(record).metadata??{};}
const playlists=computed<any[]>(()=>Array.isArray(store.value.playlists)?store.value.playlists:store.value.playlists?.items??[]);
const records=computed(()=>{
  const local:NormalizedRecord[]=props.library.library.assets.map(a=>normalizeAsset(a)),youtube:NormalizedRecord[]=(imported.value??channel.value.videos??[]).map((v:any)=>normalizeYoutube(v));
  return [...youtube,...local].filter((r,i,all)=>all.findIndex(x=>key(x)===key(r))===i).map(r=>{
    const saved=savedRecord(r),meta={...savedMetadata(r),...overrides.value[key(r)]};
    if(r.kind==='local')for(const field of ['description','tags','categoryId','privacy'])if(saved.fields?.[field]!==undefined)(r as any)[field]=saved.fields[field];
    for(const field of ['creator','roomId','platform','recordedAt','recordedEnd','sessionTitle','sourceUrl','part','labels','copyrightStatus','localAssetId','playlistId','originalTitle','technicalFields','manualFields'])if(meta[field]!==undefined)(r as any)[field]=meta[field];
    if(Array.isArray(saved.metadata?.evidence))r.evidence.push(...saved.metadata.evidence);
    for(const field of meta.manualFields??[])r.evidence.push({field,value:String((r as any)[field]),source:'人工校正',confidence:'high'});
    return r;
  });
});
const filtered=computed(()=>records.value.filter(r=>(kind.value==='all'||r.kind===kind.value)&&(!privacy.value||r.privacy===privacy.value)&&(!search.value||`${r.title} ${r.creator} ${r.roomId} ${r.id} ${r.labels?.join(' ')}`.toLowerCase().includes(search.value.toLowerCase()))));
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/25))),currentPage=computed(()=>Math.min(page.value,pages.value)),visible=computed(()=>filtered.value.slice((currentPage.value-1)*25,currentPage.value*25));
const targets=computed(()=>records.value.filter(r=>selection.value.has(key(r))));
const hidden=computed(()=>selection.value.size-filtered.value.filter(r=>selection.value.has(key(r))).length);
const results=computed(()=>(preview.value?.records??[]).filter(r=>!previewFilter.value||r.status===previewFilter.value));
const resultPages=computed(()=>Math.max(1,Math.ceil(results.value.length/20))),visibleResults=computed(()=>results.value.slice((Math.min(previewPage.value,resultPages.value)-1)*20,Math.min(previewPage.value,resultPages.value)*20));
const eligible=computed(()=>(preview.value?.records??[]).filter(r=>r.status==='ready'||(r.status==='review'&&approved.value.has(key(r.after)))));
const statuses:Record<string,string>={ready:'可应用',review:'待复核',unchanged:'无变化',skipped:'已跳过',blocked:'已阻止',preview:'已冻结预览',pending:'待应用',completed:'已完成',failed:'失败',partial:'部分完成',interrupted:'已中断',running:'执行中',unknown:'结果待核实'};
const currentAsset=computed(()=>props.library.library.assets.find(a=>a.id===assetLink.value));
const playableAssets=computed(()=>props.library.library.assets.filter(a=>a.extension==='mp4'));
watch([search,kind,privacy],()=>page.value=1);watch(previewFilter,()=>previewPage.value=1);
watch(()=>JSON.stringify({graph:{...graph.value,nodes:graph.value.nodes.map(({position,...node})=>node)},selection:[...selection.value],overrides:overrides.value,frames:frames.value,imported:importedName.value}),()=>{preview.value=null;run.value=null;approved.value=new Set();});
watch(()=>JSON.stringify({records:records.value,playlists:playlists.value}),()=>{if(!busy.value){preview.value=null;if(['pending','preview'].includes(run.value?.status))run.value=null;approved.value=new Set();}});
watch(()=>props.selectionRequest,request=>{if(request){kind.value=request.kind;selection.value=new Set(request.ids.map(id=>`${request.kind}:${id}`));tab.value='data';}},{immediate:true});
watch(focus,value=>{assetLink.value=value?.kind==='local'?value.id:(value as any)?.localAssetId??'';});
onMounted(()=>perform(async()=>{await load();loadIdentityDraft();}));
function toggle(record:NormalizedRecord){const next=new Set(selection.value);next.has(key(record))?next.delete(key(record)):next.add(key(record));selection.value=next;}
function selectList(list:NormalizedRecord[]){selection.value=new Set([...selection.value,...list.map(key)]);}
function setOverride(field:string,value:any){if(!focus.value)return;const manualFields=[...new Set([...(savedMetadata(focus.value).manualFields??[]),...(overrides.value[key(focus.value)]?.manualFields??[]),field])];overrides.value={...overrides.value,[key(focus.value)]:{...overrides.value[key(focus.value)],[field]:value,manualFields}};focus.value={...focus.value,[field]:value};}
function approve(record:RecordPreview){const next=new Set(approved.value);next.has(key(record.after))?next.delete(key(record.after)):next.add(key(record.after));approved.value=next;run.value=null;}
function applyTemplate(){graph.value=createTemplate(template.value);graph.value.id=crypto.randomUUID();tab.value='canvas';nextTick(()=>canvasRef.value?.fit());}
function useDraft(draft:any){graph.value=parseWorkflowGraph(draft.graph);tab.value='canvas';nextTick(()=>canvasRef.value?.fit());}
async function saveDraft(){await perform(async()=>{await api('/workflows/drafts',{id:graph.value.id,name:graph.value.name,graph:graph.value});await load(true);message.value='管线已保存到本机数据库。';});}
function download(name:string,data:string,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importGraph(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(file)await perform(async()=>{if(file.size>1024*1024)throw Error('模板文件过大');graph.value=parseWorkflowGraph(JSON.parse(await file.text()));tab.value='canvas';message.value='模板已导入，保存后可跨会话复用。';});input.value='';}
async function importSnapshot(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(file)await perform(async()=>{if(file.size>32*1024*1024)throw Error('快照不能超过 32 MiB');const data=JSON.parse(await file.text()),videos=Array.isArray(data)?data:data.videos;if(!Array.isArray(videos)||!videos.every(v=>typeof v.id==='string'&&typeof v.snippet?.title==='string'))throw Error('请选择包含 videos 数组的频道研究快照');imported.value=videos;importedName.value=file.name;selection.value=new Set();kind.value='youtube';tab.value='data';message.value='已导入研究快照，仅用于本地预览和导出。切回当前频道才能提交远端应用。';});input.value='';}
function context(){
  const ledger=(store.value.identityLedger?.items??[]) as IdentityBinding[];
  const fromRecords=records.value.filter(r=>r.creator&&r.roomId&&r.platform&&r.platform!=='unknown'&&['creator','roomId','platform'].every(field=>r.evidence.some(e=>e.field===field&&e.value===(r as any)[field]&&e.confidence==='high'))).map(r=>({platform:r.platform,roomId:r.roomId,creator:r.creator,playlistId:(r as any).playlistId}));
  return {
    playlists:playlists.value.map((p:any)=>({id:p.id,title:p.title??p.snippet?.title??'',description:p.description??p.snippet?.description??'',video_ids:p.video_ids??[]})),
    identityBindings:fromRecords,
    identityLedger:ledger,
    records:records.value,
  };
}
function dryRun(){error.value='';message.value='';try{if(!targets.value.length)throw Error('请先选择输入视频或素材');preview.value=runWorkflow(graph.value,copy(targets.value),context());for(const result of preview.value.records){const edits=overrides.value[key(result.after)]??{};for(const [field,value] of Object.entries(edits)){if(field==='thumbnail'||field==='manualFields')continue;if(!result.changes.some(c=>c.field===field))result.changes.push({field,before:savedMetadata(result.before)[field]??'',after:value});}if(frames.value[key(result.after)])result.changes.push({field:'封面',before:'当前封面',after:`本地画面 ${frames.value[key(result.after)]!.time_seconds.toFixed(2)} 秒`});if(result.status==='unchanged'&&(Object.keys(edits).length||frames.value[key(result.after)]))result.status='ready';}preview.value.summary.ready=preview.value.records.filter(r=>r.status==='ready').length;preview.value.summary.changed=preview.value.records.filter(r=>r.changes.length).length;approved.value=new Set();run.value=null;tab.value='preview';previewPage.value=1;if(!preview.value.valid)error.value=preview.value.errors.join('；');}catch(e){error.value=(e as Error).message;}}
function metadata(r:NormalizedRecord){const result:Record<string,any>={};for(const field of ['manualFields','creator','roomId','platform','recordedAt','recordedEnd','sessionTitle','part','sourceUrl','labels','copyrightStatus','localAssetId','playlistId','originalTitle','technicalFields','thumbnailCandidate','aiProposal','evidence','issues'])if((r as any)[field]!==undefined)result[field]=(r as any)[field];return result;}
function fields(r:NormalizedRecord){return {title:r.title,description:r.description,tags:r.tags,categoryId:r.categoryId,privacy:r.privacy};}
async function freeze(){await perform(async()=>{if(imported.value&&eligible.value.some(r=>r.after.kind==='youtube'))throw Error('研究快照仅用于预览，请切回当前频道并重新预览');if(!eligible.value.length)throw Error('没有可应用项目，请处理待复核项');const items=eligible.value.map(r=>{const actionable=(r.playlistIntents??[]).filter((p:any)=>p.action!=='review');if(actionable.length>1)throw Error('当前应用计划每个视频支持一个播放列表，请拆分播放列表节点后重新预览');const intent=actionable[0];return {id:r.id,kind:r.after.kind,before:fields(r.before),after:fields(r.after),metadata:metadata(r.after),...(intent?{playlist:intent}:{}),...(frames.value[key(r.after)]?{thumbnail:frames.value[key(r.after)]}:{})};});run.value=await api('/workflows/preview',{name:graph.value.name,graph:graph.value,items});message.value=`已冻结 ${run.value.items.length} 项变更，请核对后应用。`;});}
async function execute(){await perform(async()=>{run.value=await api(`/workflows/runs/${encodeURIComponent(run.value.id)}/apply`,{});await load(true);emit('refresh');message.value='执行已返回，请查看逐项结果。失败项目保留原计划，可以重试。';});}
async function syncPlaylists(){await perform(async()=>{await api('/workflows/playlists/sync',{});await load();preview.value=null;run.value=null;message.value='播放列表与成员已同步。';});}
async function capture(){await perform(async()=>{const video=player.value;if(!focus.value||!video||!currentAsset.value||video.readyState<2||!video.videoWidth)throw Error('请先加载并暂停到要选取的视频画面');video.pause();const canvas=document.createElement('canvas');const ratio=Math.min(1,1280/video.videoWidth);canvas.width=Math.round(video.videoWidth*ratio);canvas.height=Math.round(video.videoHeight*ratio);canvas.getContext('2d')!.drawImage(video,0,0,canvas.width,canvas.height);const frame={asset_id:currentAsset.value.id,time_seconds:video.currentTime,data_url:canvas.toDataURL('image/jpeg',.88)};frames.value={...frames.value,[key(focus.value)]:frame};setOverride('localAssetId',currentAsset.value.id);setOverride('thumbnail',frame);message.value='当前帧已加入此视频的封面候选，生成变更预览后应用。';});}
function exportPreview(){download('workflow-preview.json',JSON.stringify({name:graph.value.name,generatedAt:new Date().toISOString(),graph:graph.value,preview:preview.value},null,2));}
</script>

<template>
<div class="workflow-studio">
  <div class="page-heading"><div><div class="eyebrow">CHANNEL & LIBRARY WORKFLOWS</div><h1>自定义管线<span class="heading-dot">.</span></h1><p>用同一套模块整理已上传视频与本地素材，逐步预览，再应用变更。</p></div><button class="subtle" :disabled="busy" @click="perform(load)"><RefreshCw :size="15"/>刷新资料</button></div>
  <div v-if="error" class="warning-panel" role="alert">{{error}}</div><div v-if="message" class="flow-message" role="status">{{message}}</div>
  <div class="flow-workbar"><div class="flow-name"><Workflow :size="18"/><input v-model="graph.name" aria-label="管线名称"/></div><select v-model="template" aria-label="选择管线模板"><option v-for="t in WORKFLOW_TEMPLATES" :key="t.key" :value="t.key">{{t.name}}</option></select><button class="subtle" @click="applyTemplate">使用模板</button><button class="subtle" :disabled="busy" @click="saveDraft"><Save :size="15"/>保存</button><button class="subtle" @click="download('u2bup-workflow.json',JSON.stringify(graph,null,2))" title="导出可复用管线模板"><Download :size="15"/>导出</button><label class="subtle flow-file"><Upload :size="15"/>导入<input type="file" accept=".json" @change="importGraph"/></label><button class="primary" :disabled="busy||!targets.length" @click="dryRun"><Play :size="15"/>预览 {{targets.length}} 项</button></div>
  <div class="flow-tabs" role="tablist" aria-label="管线工作区"><button v-for="t in [{id:'canvas',label:'模块画布'},{id:'modules',label:'模块管理'},{id:'data',label:'输入数据'},{id:'preview',label:'差异与复核'},{id:'history',label:'保存与运行记录'}]" :key="t.id" role="tab" :aria-selected="tab===t.id" :class="{active:tab===t.id}" @click="tab=t.id;if(t.id==='modules'){moduleCatalog=listAllModules();loadIdentityDraft();}">{{t.label}}<span v-if="t.id==='data'">{{selection.size}}</span><span v-if="t.id==='preview'&&preview">{{preview.summary.changed}}</span></button><span class="flow-local-label">手动触发 · 本机保存 · 插件化预览</span></div>
  <WorkflowCanvas v-show="tab==='canvas'" ref="canvasRef" v-model="graph"/>
  <section v-if="tab==='modules'" class="panel flow-data">
    <div class="flow-section-heading"><div><h2>管线模块</h2><p>内置模块默认可用以保证兼容；声明式 L1 包可安装、启用并出现在画布模块库。远端写入仍由宿主 Intent 执行。</p></div><div class="flow-actions"><button class="subtle" :disabled="busy" @click="installExample">安装示例标签词典</button><label class="subtle flow-file"><Upload :size="15"/>安装 JSON 模块<input type="file" accept=".json" @change="installModuleFile"/></label></div></div>
    <div class="table-wrap"><table><thead><tr><th>模块</th><th>来源</th><th>能力</th><th>启用</th><th></th></tr></thead><tbody>
      <tr v-for="mod in moduleCatalog" :key="mod.id"><td><strong>{{mod.label}}</strong><small class="block muted">{{mod.id}} · {{mod.type}}</small><p class="flow-help">{{mod.description}}</p></td><td><span class="badge neutral">{{mod.source==='builtin'?'内置':'本地 L1'}}</span></td><td><small>{{mod.capabilities.join(' · ')||'—'}}</small></td><td><label class="flow-check"><input type="checkbox" :checked="mod.enabled" @change="toggleModule(mod.id,($event.target as HTMLInputElement).checked,mod.source==='builtin')"/></label></td><td><button v-if="mod.source==='local'" class="text-action" @click="removeModule(mod.id)">卸载</button></td></tr>
    </tbody></table></div>
    <h2 style="margin-top:28px">来源身份台账</h2>
    <p class="flow-help">每行：platform|roomId|creator|可选别名。供「来源身份台账」节点与播放列表匹配使用；不会因裸数字推断平台。</p>
    <textarea v-model="identityDraft" rows="8" aria-label="身份台账" placeholder="bilibili|12345|主播甲|甲甲"></textarea>
    <div class="flow-actions" style="margin-top:12px"><button class="primary" :disabled="busy" @click="saveIdentityLedger">保存身份台账</button><button class="subtle" @click="loadIdentityDraft">重新载入</button></div>
  </section>
  <section v-if="tab==='data'" class="panel flow-data">
    <div class="flow-section-heading"><div><h2>选择管线输入</h2><p>{{imported?`研究快照：${importedName} · 仅预览`:'读取当前频道缓存与本地素材库'}} · {{records.length}} 项</p></div><div class="flow-actions"><label class="subtle flow-file"><FileJson :size="14"/>导入研究快照<input type="file" accept=".json" @change="importSnapshot"/></label><button v-if="imported" class="subtle" @click="imported=null;importedName='';selection=new Set()">切回当前频道</button><button class="subtle" :disabled="busy||!channel.connected" @click="syncPlaylists">同步播放列表</button></div></div>
    <div class="flow-input-filters"><div class="search-input"><Search :size="15"/><input v-model="search" aria-label="搜索管线输入" placeholder="标题、主播、房间、视频 ID…"/></div><select v-model="kind" aria-label="筛选输入来源"><option value="youtube">已上传视频</option><option value="local">本地待上传素材</option><option value="all">全部来源</option></select><select v-model="privacy" aria-label="筛选公开状态"><option value="">全部公开状态</option><option value="private">私密</option><option value="unlisted">不公开</option><option value="public">公开</option></select></div>
    <div class="flow-selectbar"><strong>已选 {{selection.size}} 项</strong><span>筛选外 {{hidden}} 项</span><button @click="selectList(filtered)">选全部筛选结果</button><button @click="selectList(visible)">选本页</button><button @click="selection=new Set()" :disabled="!selection.size">取消全部</button><span class="flow-select-limit">提交最多 100 项 / 批；预览可覆盖全部</span></div>
    <div v-if="!filtered.length" class="empty"><Workflow :size="28"/><h3>暂无符合条件的数据</h3><p>可切换到本地素材、同步频道视频，或导入 channel-snapshot.json 试跑。</p><button class="subtle" @click="emit('navigate','/youtube/videos')">前往频道视频</button></div>
    <div v-else class="table-wrap"><table><thead><tr><th></th><th>视频 / 素材</th><th>来源</th><th>主播 / 房间</th><th>标签</th><th></th></tr></thead><tbody><tr v-for="record in visible" :key="key(record)" :class="{checked:selection.has(key(record))}"><td><input type="checkbox" :aria-label="'选择 '+record.title" :checked="selection.has(key(record))" @change="toggle(record)"/></td><td class="flow-title-cell"><strong>{{record.title}}</strong><small>{{record.id}}</small></td><td><span class="badge neutral">{{record.kind==='youtube'?'YouTube':'本地素材'}}</span></td><td>{{record.creator||'待识别'}}<small class="block muted">{{record.roomId||'房间未知'}}</small></td><td>{{record.tags.length?record.tags.slice(0,3).join(' · '):'待补齐'}}</td><td><button class="text-action" @click="focus=copy(record)">校正 / 封面</button></td></tr></tbody></table></div>
    <div class="table-footer"><span>{{filtered.length}} 项 · 当前 {{currentPage}} / {{pages}} 页</span><div class="pager"><button aria-label="输入上一页" :disabled="currentPage===1" @click="page=currentPage-1"><ChevronLeft :size="16"/></button><button aria-label="输入下一页" :disabled="currentPage===pages" @click="page=currentPage+1"><ChevronRight :size="16"/></button></div></div>
  </section>
  <section v-if="tab==='preview'" class="flow-preview">
    <div v-if="!preview" class="panel empty"><Play :size="28"/><h3>先试跑，查看每一步的结果</h3><p>在输入数据中选择视频，点击「预览」。修改规则或输入后，旧预览会失效。</p><button class="subtle" @click="tab='data'">选择输入数据</button></div>
    <template v-else><div class="flow-preview-heading"><div><h2>差异预览</h2><p>{{preview.summary.total}} 项输入 · {{preview.summary.ready}} 项可应用 · {{preview.summary.review}} 项待复核 · {{preview.summary.blocked}} 项已阻止</p></div><div class="flow-actions"><button class="subtle" @click="exportPreview"><Download :size="14"/>导出预览</button><button class="primary" :disabled="busy||!eligible.length||eligible.length>100||!preview.valid" @click="freeze">生成 {{eligible.length}} 项应用计划<ArrowRight :size="15"/></button></div></div>
    <p class="flow-help">复核只确认本次元信息建议；版权声明、地区限制分别保留。未执行的 AI 能力不会生成虚构结果。</p>
    <div v-if="eligible.length>100" class="warning-panel">超过每批 100 项。请缩小输入选择后重新预览。</div>
    <select v-model="previewFilter" aria-label="按预览结果筛选"><option value="">全部结果</option><option v-for="s in ['ready','review','blocked','unchanged','skipped']" :key="s" :value="s">{{statuses[s]}}</option></select>
    <article v-for="result in visibleResults" :key="key(result.after)" class="panel flow-result"><div class="flow-result-title"><span class="badge" :class="result.status==='ready'?'green':result.status==='review'||result.status==='blocked'?'amber':'neutral'">{{statuses[result.status]}}</span><h3>{{result.before.title}}</h3><button class="text-action" @click="focus=copy(result.after)">校正资料</button></div><div v-if="result.changes.length" class="flow-diffs"><div v-for="change in result.changes" :key="change.field"><span>{{({title:'标题',description:'描述',tags:'标签',labels:'内容分类',categoryId:'YouTube 分类',privacy:'公开状态'} as Record<string,string>)[change.field]??change.field}}</span><pre>{{Array.isArray(change.before)?change.before.join(' · '):change.before||'（空）'}}</pre><ArrowRight :size="14"/><pre class="flow-after">{{Array.isArray(change.after)?change.after.join(' · '):change.after||'（空）'}}</pre></div></div><div v-for="intent in result.playlistIntents" :key="intent.identityKey" class="flow-intent"><Link2 :size="14"/><span>播放列表：{{intent.title}} · {{intent.reason}}</span></div><ul v-if="result.issues.length" class="flow-issues"><li v-for="(issue,i) in result.issues" :key="i">{{issue.message}}</li></ul><details><summary>查看节点运行轨迹与识别证据</summary><ol><li v-for="trace in result.trace" :key="trace.nodeId">{{graph.nodes.find(n=>n.id===trace.nodeId)?.type}} · {{trace.message}}</li></ol><p v-for="(evidence,i) in result.after.evidence" :key="i">{{evidence.field}} = {{evidence.value}} · {{evidence.source}} · {{evidence.confidence}}</p></details><label v-if="result.status==='review'" class="flow-check"><input type="checkbox" :checked="approved.has(key(result.after))" @change="approve(result)"/>已逐项核对本次建议，允许加入应用计划</label></article>
    <div class="table-footer"><span>{{results.length}} 项结果</span><div class="pager"><button aria-label="预览上一页" :disabled="previewPage<=1" @click="previewPage--"><ChevronLeft :size="16"/></button><span>{{Math.min(previewPage,resultPages)}} / {{resultPages}}</span><button aria-label="预览下一页" :disabled="previewPage>=resultPages" @click="previewPage++"><ChevronRight :size="16"/></button></div></div>
    </template>
    <section v-if="run" class="panel flow-frozen"><div class="flow-section-heading"><div><h2>已冻结的应用计划</h2><p>{{run.name}} · {{run.items.length}} 项 · {{run.items.filter((i:any)=>i.kind==='youtube').length}} 个远端视频 · {{statuses[run.status]??run.status}}</p></div><button class="primary" :disabled="busy||run.status==='completed'" @click="execute"><Check :size="15"/>{{run.items.some((i:any)=>i.status==='failed')?'重试未完成项':'确认应用这些变更'}}</button></div><div class="flow-run-scroll"><div v-for="item in run.items" :key="item.kind+item.id" class="flow-run-item"><strong>{{item.after.title}}</strong><span>{{statuses[item.status]??item.status}} · {{item.message}}</span><details><summary>核对已冻结的字段与独立动作</summary><pre>{{JSON.stringify({before:item.before,after:item.after,actions:item.actions},null,2)}}</pre><div v-if="item.playlist"><strong>播放列表：{{item.playlist.title}}</strong><p>原说明：{{item.playlist_before?.snippet?.description||'（空）'}}</p><pre>{{item.playlist.description}}</pre></div><img v-if="item.thumbnail?.image_id" :src="`/api/workflows/thumbnails/${item.thumbnail.image_id}`" class="flow-frozen-frame" alt="应用计划中的封面"/></details></div></div></section>
  </section>
  <section v-if="tab==='history'" class="flow-history"><div class="panel"><h2>已保存管线</h2><p v-if="!store.drafts.length">尚未保存。配置画布后点击「保存」。</p><div v-for="draft in store.drafts" :key="draft.id" class="flow-history-row"><div><strong>{{draft.name}}</strong><small>{{draft.graph?.nodes?.length??0}} 个节点</small></div><button class="subtle" @click="useDraft(draft)">载入管线</button></div></div><div class="panel"><h2>运行与应用记录</h2><p v-if="!store.runs.length">生成应用计划后，将保留原始值、规则快照和逐项结果。</p><div v-for="saved in store.runs" :key="saved.id" class="flow-history-row"><div><strong>{{saved.name}}</strong><small>{{saved.items?.length??0}} 项 · {{statuses[saved.status]??saved.status}} · {{new Date(saved.created_at).toLocaleString('zh-CN')}}</small></div><button class="subtle" @click="run=saved;tab='preview'">查看结果</button></div></div></section>
  <div v-if="focus" class="drawer-backdrop" @click.self="focus=null"><aside class="drawer flow-record-drawer"><div class="drawer-heading"><span>资料校正与封面</span><button class="icon-button" aria-label="关闭资料校正" @click="focus=null"><X :size="20"/></button></div><div class="drawer-content"><h2>{{focus.title}}</h2><p>校正信息将用于下一次预览，应用后保存到本机档案。</p><div class="flow-identity-fields"><label class="field-label">主播名称<input :value="focus.creator" @change="setOverride('creator',($event.target as HTMLInputElement).value)"/></label><label class="field-label">来源平台<select :value="focus.platform" @change="setOverride('platform',($event.target as HTMLSelectElement).value)"><option value="unknown">未知</option><option value="bilibili">Bilibili 直播</option><option value="twitch">Twitch</option><option value="youtube">YouTube</option><option value="other">其他</option></select></label><label class="field-label">房间 ID<input :value="focus.roomId" @change="setOverride('roomId',($event.target as HTMLInputElement).value)"/></label><label class="field-label">录制时间（保留时区）<input :value="focus.recordedAt" @change="setOverride('recordedAt',($event.target as HTMLInputElement).value)"/></label></div><label class="field-label">原直播主题<input :value="focus.sessionTitle" @change="setOverride('sessionTitle',($event.target as HTMLInputElement).value)"/></label><label class="field-label">明确绑定播放列表<select :value="(focus as any).playlistId??''" @change="setOverride('playlistId',($event.target as HTMLSelectElement).value)"><option value="">按房间证据匹配</option><option v-for="p in playlists" :key="p.id" :value="p.id">{{p.title??p.snippet?.title}} · {{p.id}}</option></select></label><label class="field-label">版权复核记录<select :value="focus.copyrightStatus" @change="setOverride('copyrightStatus',($event.target as HTMLSelectElement).value)"><option value="unknown">未知 / 尚未核对 Studio</option><option value="claim">Content ID 声明，待处理</option><option value="strike">版权警告，待处理</option><option value="clear">已人工核对 Studio：当前无声明 / 警告</option></select></label><p class="flow-help">这里只记录复核情况。申诉、静音和裁剪需在 YouTube Studio 处理。</p><h3 class="flow-frame-heading"><Image :size="17"/>选取当前帧作为封面</h3><label class="field-label">关联可播放的本地 MP4<select v-model="assetLink" @change="setOverride('localAssetId',assetLink)"><option value="">选择对应素材…</option><option v-for="asset in playableAssets" :key="asset.id" :value="asset.id">{{asset.display_title??asset.title}} · {{asset.name}}</option></select></label><video v-if="currentAsset" :key="currentAsset.id" ref="player" :src="`/api/assets/${encodeURIComponent(currentAsset.id)}/media`" controls preload="metadata" class="detail-preview"/><p v-else>关联本地素材后可取帧；仅有 YouTube 元信息时无法提取远端视频画面。</p><button class="subtle" :disabled="busy||!currentAsset" @click="capture"><Image :size="15"/>选定当前帧</button><template v-if="frames[key(focus)]"><img :src="frames[key(focus)]!.data_url" class="flow-frame-preview" alt="本次选取的封面候选"/><p>{{frames[key(focus)]!.time_seconds.toFixed(2)}} 秒 · 将随应用计划保存</p><button class="text-action" @click="delete frames[key(focus)]">移除封面候选</button></template><button class="primary full" @click="focus=null">完成校正，重新预览</button></div></aside></div>
</div>
</template>

